def is_balanced(s):
    """Return True when brackets in s are balanced, False otherwise.
    Raises TypeError if s is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    stack = []
    for ch in s:
        if ch in OPEN:
            stack.append(ch)
        elif ch in CLOSE:
            if not stack or stack[-1] != PAIRS[ch]:
                return False
            stack.pop()
    return not stack

